function fitArts(){artFitFrame=0;document.querySelectorAll('.art-shell').forEach(function(shell){var width=shell.getBoundingClientRect().width,frame=shell.querySelector('.art-window');if(!shell.classList.contains('uploaded')&&width>0&&frame)frame.style.transform='scale('+(width/1080)+')';});}
